package commands

import (
	"fmt"
	"io"
	"os/exec"
	"strings"
)

// aiAttributionPatterns matches common AI-attribution strings in tracked files.
var aiAttributionPatterns = []string{
	"Co-Authored-By: Claude",
	"Co-Authored-By: GPT",
	"Co-Authored-By: Gemini",
	"Generated with Claude",
	"Generated with GPT",
	"Made with Claude",
	"🤖 Generated",
	"generated by AI",
	"generated by claude",
	"claude-code",
}

func handlePrivacy(_ string, w io.Writer) (bool, error) {
	r := runCmd("git", "ls-files")
	if r.ReturnCode != 0 {
		fmt.Fprintln(w, "error: not in a git repository")
		return true, nil
	}

	files := strings.Fields(r.Stdout)
	if len(files) == 0 {
		fmt.Fprintln(w, "no tracked files found")
		return true, nil
	}

	type hit struct {
		file string
		line int
		text string
	}
	var hits []hit

	for _, file := range files {
		grepArgs := []string{"grep", "-n", "-i"}
		// Build a single grep with alternation.
		pattern := strings.Join(aiAttributionPatterns, "\\|")
		grepArgs = append(grepArgs, pattern, file)

		cmd := exec.Command(grepArgs[0], grepArgs[1:]...)
		out, _ := cmd.Output()
		if len(out) == 0 {
			continue
		}
		for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if line == "" {
				continue
			}
			parts := strings.SplitN(line, ":", 2)
			if len(parts) < 2 {
				continue
			}
			lineNum := 0
			fmt.Sscanf(parts[0], "%d", &lineNum)
			hits = append(hits, hit{file: file, line: lineNum, text: strings.TrimSpace(parts[1])})
		}
	}

	if len(hits) == 0 {
		fmt.Fprintln(w, "no AI attribution patterns found")
		return true, nil
	}

	fmt.Fprintf(w, "found %d potential AI attribution(s):\n", len(hits))
	for _, h := range hits {
		fmt.Fprintf(w, "  %s:%d  %s\n", h.file, h.line, h.text)
	}
	return true, nil
}
